`,ni=()=>(0,va.jsxs)(Ja,{children:[(0,va.jsxs)(Xa,{children:[(0,va.jsxs)(Fa,{children:[(0,va.jsx)(ti,{src:"./favicon.ico"}),(0,va.jsx)(Za,{children:ga.name})]}),(0,va.jsxs)(Fa,{children:[(0,va.jsx)(Ya,{source:"/images/logos/github.png",size:75,margin:12,linkTo:ga.links.github}),(0,va.jsx)(Ya,{source:"/images/logos/linkedIn.png",size:75,margin:12,linkTo:ga.links.linkedIn}),(0,va.jsx)(Ya,{source:"/images/logos/itch.io.png",size:75,margin:12,linkTo:ga.links.itchIO})]})]}),(0,va.jsx)(ei,{children:ga.introduction})]}),ri="PiPiK",ai="Game Programmer",ii="These are some techniques and design patterns i've used in my projects",oi="/images/Profile.jpg",li="/CV.pdf",si=[{category:"Language Program",icon:"\ud83d\udcda",items:["C# (Unity)"]},{category:"Tools",icon:"\u2699\ufe0f",items:["Unity Engine","Git/Git LFS","ShaderGraph","DOTS","Jobs System"]},{category:"Technique",icon:"\u2699\ufe0f",items:["Refactor","Clean Code","SOLID Principle"]}],ci=[{name:"Singleton",type:"Creational",description:"\u0110\u1ea3m b\u1ea3o m\u1ed9t l\u1edbp ch\u1ec9 c\xf3 m\u1ed9t th\u1ec3 hi\u1ec7n duy nh\u1ea5t v\xe0 cung c\u1ea5p m\u1ed9t \u0111i\u1ec3m truy c\u1eadp to\xe0n c\u1ee5c t\u1edbi n\xf3.",useCase:"Ph\xf9 h\u1ee3p cho GameManager, AudioManager, ho\u1eb7c b\u1ea5t k\u1ef3 h\u1ec7 th\u1ed1ng n\xe0o ch\u1ec9 n\xean c\xf3 m\u1ed9t instance.",code:" public abstract class Singleton<T> : MonoBehaviour where T : MonoBehaviour\n{\n    private static T _instance;\n    public static T Instance\n    {\n        get\n        {\n            if (_instance == null)\n            {\n                _instance = FindObjectOfType<T>();\n\n                if (_instance == null)\n                {\n                    GameObject go = new GameObject(typeof(T).Name);\n                    _instance = go.AddComponent<T>();\n                }\n            }\n            return _instance;\n        }\n    }\n\n    protected virtual void Awake()\n    {\n        if (_instance == null)\n        {\n            _instance = this as T;\n            DontDestroyOnLoad(gameObject);\n        }\n        else if (_instance != this)\n        {\n            Destroy(gameObject);\n        }\n    }\n}"},{name:"Object Pool",type:"Creational",description:"T\xe1i s\u1eed d\u1ee5ng c\xe1c \u0111\u1ed1i t\u01b0\u1ee3ng thay v\xec t\u1ea1o m\u1edbi v\xe0 h\u1ee7y ch\xfang li\xean t\u1ee5c, gi\xfap c\u1ea3i thi\u1ec7n hi\u1ec7u su\u1ea5t.",useCase:"Thi\u1ebft y\u1ebfu cho \u0111\u1ea1n, hi\u1ec7u \u1ee9ng h\u1ea1t, k\u1ebb th\xf9, ho\u1eb7c b\u1ea5t k\u1ef3 \u0111\u1ed1i t\u01b0\u1ee3ng n\xe0o \u0111\u01b0\u1ee3c sinh ra th\u01b0\u1eddng xuy\xean.",code:'public class ObjectPool : ServicePrefab\n{\n    [SerializeField] \n    private bool dontDestroyonLoad;\n\n    private GameObject emptyHolder;\n\n    private GameObject particleSystemHolder;\n    private GameObject gameObjectHolder;\n    private GameObject soundFxHolder;\n\n    private Dictionary<GameObject, ObjectPool<GameObject>> objectPools;\n    private Dictionary<GameObject, GameObject> clonePrefabMap;\n\n    public enum PoolType\n    {\n        GameObject,\n        Particle,\n        SoundFx\n    }\n\n    public PoolType PoolingType;\n\n    public override void OnAwake()\n    {\n        base.OnAwake();\n        objectPools = new Dictionary<GameObject, ObjectPool<GameObject>>();\n        clonePrefabMap = new Dictionary<GameObject, GameObject>();\n\n        SetUpHolder();\n    }\n\n    private void SetUpHolder()\n    {\n        emptyHolder = new GameObject("Object_Pool");\n\n        gameObjectHolder = new GameObject("GameObjects");\n        gameObjectHolder.transform.SetParent(emptyHolder.transform);\n\n        particleSystemHolder = new GameObject("ParticleSystems");\n        particleSystemHolder.transform.SetParent(emptyHolder.transform);\n\n        soundFxHolder = new GameObject("SoundFX");\n        soundFxHolder.transform.SetParent(emptyHolder.transform);\n    }\n\n    public void CreatePool(GameObject gameObject, Vector3 pos, Quaternion rot, PoolType poolType = PoolType.GameObject)\n    {\n        ObjectPool<GameObject> pool = new ObjectPool<GameObject>(\n            createFunc: ()=> CreateObject(gameObject,pos,rot,poolType),\n            actionOnGet:OnGetObject,\n            actionOnRelease:OnReleaseObject,\n            actionOnDestroy:OnDestroyObject\n            );\n\n        objectPools.Add(gameObject,pool);\n    }\n\n    public GameObject CreateObject(GameObject gameObject, Vector3 pos, Quaternion rot, PoolType poolType = PoolType.GameObject)\n    {\n        gameObject.SetActive(false);\n        GameObject obj = Instantiate(gameObject, pos, rot);\n        gameObject.SetActive(true);\n\n        GameObject parent = SetParentObject(poolType);\n        obj.transform.SetParent(parent.transform);\n\n        return obj;\n    }\n\n    private GameObject SetParentObject(PoolType poolType)\n    {\n        switch (poolType)\n        {\n            case PoolType.GameObject:\n                return gameObjectHolder;\n            case PoolType.Particle:\n                return particleSystemHolder;\n            case PoolType.SoundFx:\n                return soundFxHolder;\n            default:\n                return null;\n        }\n    }\n\n    public void OnGetObject(GameObject gameObject)\n    {\n\n    }\n    public void OnReleaseObject(GameObject gameObject)\n    {\n        gameObject.SetActive(false);\n    }\n    public void OnDestroyObject(GameObject gameObject)\n    {\n        if (clonePrefabMap.ContainsKey(gameObject))\n        {\n            clonePrefabMap.Remove(gameObject);\n        }\n    }\n\n    public T SpawnObject<T>(GameObject objectToSpawn, Vector3 pos, Quaternion rot, PoolType poolType = PoolType.GameObject) where T : UnityEngine.Object\n    {\n        if(!objectPools.ContainsKey(objectToSpawn))\n        {\n            CreatePool(objectToSpawn, pos, rot, poolType);\n        }\n\n        GameObject obj = objectPools[objectToSpawn].Get();\n\n        if (obj != null)\n        {\n                if (!clonePrefabMap.ContainsKey(obj))\n                {\n                    clonePrefabMap.Add(obj, objectToSpawn);\n                }\n                obj.transform.position = pos;\n                obj.transform.rotation = rot;\n                obj.SetActive(true);           \n\n            if (typeof(T) == typeof(GameObject))\n            {\n                return obj as T;\n            }\n            T component = obj.GetComponent<T>();\n            if (component == null)\n            {\n                return null;\n            }\n            return component;\n        }\n        return null;\n    }\n\n\n    public T SpawnObject<T>(T TypePrefab, Vector3 pos, Quaternion rot, PoolType poolType = PoolType.GameObject) where T : Component\n    {\n        return SpawnObject<T>(TypePrefab.gameObject, pos, rot, poolType);\n    }\n\n    public GameObject SpawnObject(GameObject gameObject, Vector3 pos, Quaternion rot, PoolType poolType = PoolType.GameObject)\n    {\n        return SpawnObject<GameObject>(gameObject, pos, rot, poolType);\n    }\n\n    public void ReturnObjectToPool(GameObject gameObject,PoolType poolType = PoolType.GameObject)\n    {\n        if(clonePrefabMap.TryGetValue(gameObject,out GameObject prefab))\n        {\n            GameObject parentObj = SetParentObject(poolType);\n\n            if(gameObject.transform.parent != parentObj.transform)\n            {\n                gameObject.transform.SetParent(parentObj.transform);\n            }\n\n            if (objectPools.TryGetValue(prefab, out ObjectPool<GameObject> pool))\n            {\n                if(gameObject.activeInHierarchy)\n                pool.Release(gameObject);\n            }\n        }\n        else\n        {\n            Debug.LogWarning("no thing to return");\n        }\n    }\n}'},{name:"State Machine",type:"Behavioral",description:"Cho ph\xe9p m\u1ed9t \u0111\u1ed1i t\u01b0\u1ee3ng thay \u0111\u1ed5i h\xe0nh vi c\u1ee7a n\xf3 khi tr\u1ea1ng th\xe1i n\u1ed9i b\u1ed9 thay \u0111\u1ed5i.",useCase:"Ho\xe0n h\u1ea3o cho AI c\u1ee7a nh\xe2n v\u1eadt, tr\u1ea1ng th\xe1i tr\xf2 ch\u01a1i, b\u1ed9 \u0111i\u1ec1u khi\u1ec3n ho\u1ea1t h\xecnh.",code:"public class StateMachine { /* ... */ }"},{name:"Behavior Tree",type:"Behavioral",description:"T\u1ea1o tr\u1ea1ng th\xe1i h\xe0nh vi cho enemy .",useCase:"Ho\xe0n h\u1ea3o cho AI enemy c\xf3 \u0111\u1ed9 ph\u1ee9c t\u1ea1p cao.",code:"public abstract class Composite : Node\n{\n    protected List<Node> Children;\n\n    public Composite(string name, List<Node> children = null) : base(name)\n    {\n        Children = children ?? new List<Node>();\n    }\n\n    public void AddChild(Node child)\n    {\n        Children.Add(child);\n    }\n}\n\npublic class Sequence : Composite\n{\n    public Sequence(string name, List<Node> children = null) : base(name, children) { }\n\n    public override Status Tick(AgentState state)\n    {\n        foreach (var child in Children)\n        {\n            CurrentStatus = child.Tick(state);\n            if (CurrentStatus != Status.SUCCESS)\n            {\n                return CurrentStatus;\n            }\n        }\n        \n        CurrentStatus = Status.SUCCESS;\n        return CurrentStatus;\n    }\n}\n\npublic class Selector : Composite\n{\n    public Selector(string name, List<Node> children = null) : base(name, children) { }\n\n    public override Status Tick(AgentState state)\n    {\n        foreach (var child in Children)\n        {\n            CurrentStatus = child.Tick(state);\n            \n            if (CurrentStatus != Status.FAILURE)\n            {\n                return CurrentStatus;\n            }\n        }\n        \n        CurrentStatus = Status.FAILURE;\n        return CurrentStatus;\n    }\n}"},{name:"Command",type:"Behavioral",description:"\u0110\xf3ng g\xf3i m\u1ed9t y\xeau c\u1ea7u th\xe0nh m\u1ed9t \u0111\u1ed1i t\u01b0\u1ee3ng ri\xeang bi\u1ec7t, cho ph\xe9p l\u01b0u l\u1ecbch s\u1eed, undo/redo v\xe0 t\xe1ch bi\u1ec7t ng\u01b0\u1eddi g\u1ecdi v\u1edbi logic th\u1ef1c thi.",useCase:"R\u1ea5t ph\xf9 h\u1ee3p cho input system, \u0111i\u1ec1u khi\u1ec3n nh\xe2n v\u1eadt, skill, combo, undo/redo h\xe0nh \u0111\u1ed9ng.",code:"\npublic interface ICommand\n{\n    void Execute();\n    void Undo();\n}\n\npublic class MoveCommand : ICommand\n{\n    private Transform player;\n    private Vector3 direction;\n    private float speed;\n\n    public MoveCommand(Transform player, Vector3 direction, float speed)\n    {\n        this.player = player;\n        this.direction = direction;\n        this.speed = speed;\n    }\n\n    public void Execute()\n    {\n        player.position += direction * speed * Time.deltaTime;\n    }\n\n    public void Undo()\n    {\n        player.position -= direction * speed * Time.deltaTime;\n    }\n}\n\npublic class InputHandler\n{\n    private Stack<ICommand> commandHistory = new Stack<ICommand>();\n\n    public void HandleCommand(ICommand command)\n    {\n        command.Execute();\n        commandHistory.Push(command);\n    }\n\n    public void Undo()\n    {\n        if (commandHistory.Count > 0)\n            commandHistory.Pop().Undo();\n    }\n}"},{name:"Factory",type:"Creational",description:"Cung c\u1ea5p m\u1ed9t interface \u0111\u1ec3 t\u1ea1o object, nh\u01b0ng cho ph\xe9p l\u1edbp con quy\u1ebft \u0111\u1ecbnh instance c\u1ee5 th\u1ec3 n\xe0o \u0111\u01b0\u1ee3c t\u1ea1o.",useCase:"T\u1ea1o enemy, bullet, item, skill m\xe0 kh\xf4ng c\u1ea7n ph\u1ee5 thu\u1ed9c tr\u1ef1c ti\u1ebfp v\xe0o class c\u1ee5 th\u1ec3.",code:'\npublic abstract class Enemy\n{\n    public abstract void Attack();\n}\n\npublic class MeleeEnemy : Enemy\n{\n    public override void Attack()\n    {\n        Debug.Log("Melee Attack");\n    }\n}\n\npublic class RangeEnemy : Enemy\n{\n    public override void Attack()\n    {\n        Debug.Log("Range Attack");\n    }\n}\n\npublic static class EnemyFactory\n{\n    public static Enemy CreateEnemy(string type)\n    {\n        switch (type)\n        {\n            case "Melee":\n                return new MeleeEnemy();\n            case "Range":\n                return new RangeEnemy();\n            default:\n                return null;\n        }\n    }\n}'},{name:"Flyweight",type:"Structural",description:"Chia s\u1ebb d\u1eef li\u1ec7u chung gi\u1eefa nhi\u1ec1u object \u0111\u1ec3 gi\u1ea3m b\u1ed9 nh\u1edb s\u1eed d\u1ee5ng.",useCase:"R\u1ea5t hi\u1ec7u qu\u1ea3 cho bullet, tile map, c\xe2y c\u1ed1i, NPC \u0111\xf4ng s\u1ed1 l\u01b0\u1ee3ng l\u1edbn.",code:'\npublic class BulletData\n{\n    public float speed;\n    public int damage;\n\n    public BulletData(float speed, int damage)\n    {\n        this.speed = speed;\n        this.damage = damage;\n    }\n}\n\npublic static class BulletDataFactory\n{\n    private static Dictionary<string, BulletData> cache = new Dictionary<string, BulletData>();\n\n    public static BulletData Get(string type)\n    {\n        if (!cache.ContainsKey(type))\n        {\n            if (type == "Normal")\n                cache[type] = new BulletData(10f, 1);\n            else if (type == "Heavy")\n                cache[type] = new BulletData(6f, 3);\n        }\n        return cache[type];\n    }\n}'},{name:"Observer",type:"Behavioral",description:"Cho ph\xe9p nhi\u1ec1u \u0111\u1ed1i t\u01b0\u1ee3ng theo d\xf5i v\xe0 ph\u1ea3n \u1ee9ng khi m\u1ed9t \u0111\u1ed1i t\u01b0\u1ee3ng kh\xe1c thay \u0111\u1ed5i tr\u1ea1ng th\xe1i.",useCase:"UI update, player health, achievement, quest system.",code:'\npublic interface IObserver\n{\n    void OnNotify();\n}\n\npublic class Subject\n{\n    private List<IObserver> observers = new List<IObserver>();\n\n    public void Subscribe(IObserver observer)\n    {\n        observers.Add(observer);\n    }\n\n    public void Unsubscribe(IObserver observer)\n    {\n        observers.Remove(observer);\n    }\n\n    public void Notify()\n    {\n        foreach (var observer in observers)\n            observer.OnNotify();\n    }\n}\n\npublic class HealthUI : IObserver\n{\n    public void OnNotify()\n    {\n        Debug.Log("Update Health UI");\n    }\n}'},{name:"Event Bus",type:"Behavioral",description:"Trung t\xe2m ph\xe2n ph\u1ed1i s\u1ef1 ki\u1ec7n gi\xfap c\xe1c h\u1ec7 th\u1ed1ng giao ti\u1ebfp m\xe0 kh\xf4ng ph\u1ee5 thu\u1ed9c tr\u1ef1c ti\u1ebfp v\xe0o nhau.",useCase:"Game flow, analytics, audio, UI, achievement, decouple h\u1ec7 th\u1ed1ng l\u1edbn.",code:"\npublic static class EventBus\n{\n    private static Dictionary<Type, Action<object>> events = new Dictionary<Type, Action<object>>();\n\n    public static void Subscribe<T>(Action<T> callback)\n    {\n        Type type = typeof(T);\n\n        if (!events.ContainsKey(type))\n            events[type] = delegate { };\n\n        events[type] += (obj) => callback((T)obj);\n    }\n\n    public static void Unsubscribe<T>(Action<T> callback)\n    {\n        Type type = typeof(T);\n\n        if (events.ContainsKey(type))\n            events[type] -= (obj) => callback((T)obj);\n    }\n\n    public static void Publish<T>(T eventData)\n    {\n        Type type = typeof(T);\n\n        if (events.ContainsKey(type))\n            events[type].Invoke(eventData);\n    }\n}\n\npublic struct PlayerDeadEvent { }\n"},{name:"Strategy",type:"Behavioral",description:"Cho ph\xe9p \u0111\u1ecbnh ngh\u0129a m\u1ed9t t\u1eadp c\xe1c thu\u1eadt to\xe1n v\xe0 ho\xe1n \u0111\u1ed5i ch\xfang v\u1edbi nhau t\u1ea1i runtime m\xe0 kh\xf4ng c\u1ea7n s\u1eeda code c\u1ee7a \u0111\u1ed1i t\u01b0\u1ee3ng s\u1eed d\u1ee5ng.",useCase:"Thay \u0111\u1ed5i h\xe0nh vi AI, c\xe1ch t\u1ea5n c\xf4ng, di chuy\u1ec3n, damage calculation, skill logic.",code:'\npublic interface IAttackStrategy\n{\n    void Attack(Transform origin);\n}\n\npublic class MeleeAttack : IAttackStrategy\n{\n    public void Attack(Transform origin)\n    {\n        Debug.Log("Melee Attack from " + origin.name);\n    }\n}\n\npublic class RangeAttack : IAttackStrategy\n{\n    public void Attack(Transform origin)\n    {\n        Debug.Log("Range Attack from " + origin.name);\n    }\n}\n\npublic class Enemy : MonoBehaviour\n{\n    private IAttackStrategy attackStrategy;\n\n    public void SetAttackStrategy(IAttackStrategy strategy)\n    {\n        attackStrategy = strategy;\n    }\n\n    public void Attack()\n    {\n        attackStrategy?.Attack(transform);\n    }\n}'},{name:"Composition Over Inheritance",type:"Principle",description:"\u01afu ti\xean k\u1ebft h\u1ee3p c\xe1c h\xe0nh vi nh\u1ecf (composition) thay v\xec k\u1ebf th\u1eeba l\u1edbp cha c\u1ed3ng k\u1ec1nh, gi\xfap code linh ho\u1ea1t, d\u1ec5 m\u1edf r\u1ed9ng v\xe0 b\u1ea3o tr\xec.",useCase:"Player/Enemy modular, skill system, weapon system, AI behavior, movement system.",code:'\npublic interface IMovable\n{\n    void Move(Vector3 direction);\n}\n\npublic interface IDamageable\n{\n    void TakeDamage(int amount);\n}\n\npublic class SimpleMovement : IMovable\n{\n    private Transform transform;\n    private float speed;\n\n    public SimpleMovement(Transform transform, float speed)\n    {\n        this.transform = transform;\n        this.speed = speed;\n    }\n\n    public void Move(Vector3 direction)\n    {\n        transform.position += direction * speed * Time.deltaTime;\n    }\n}\n\npublic class Health : IDamageable\n{\n    public int CurrentHP { get; private set; } = 100;\n\n    public void TakeDamage(int amount)\n    {\n        CurrentHP -= amount;\n        Debug.Log("HP: " + CurrentHP);\n    }\n}\n\npublic class Player : MonoBehaviour\n{\n    private IMovable movement;\n    private IDamageable health;\n\n    private void Awake()\n    {\n        movement = new SimpleMovement(transform, 5f);\n        health = new Health();\n    }\n\n    private void Update()\n    {\n        movement.Move(Vector3.forward);\n\n        if (Input.GetKeyDown(KeyCode.Space))\n            health.TakeDamage(10);\n    }\n}'}],ui=[{name:"Static Batching",category:"Draw Call Reduction",description:"K\u1ebft h\u1ee3p h\xecnh h\u1ecdc c\u1ee7a nhi\u1ec1u \u0111\u1ed1i t\u01b0\u1ee3ng t\u0129nh th\xe0nh m\u1ed9t l\u01b0\u1edbi duy nh\u1ea5t khi build, gi\u1ea3m \u0111\xe1ng k\u1ec3 l\u1ec7nh v\u1ebd (Draw Calls).",impact:"Gi\u1ea3m Draw Calls, c\u1ea3i thi\u1ec7n hi\u1ec7u su\u1ea5t CPU.",steps:["\u0110\xe1nh d\u1ea5u c\xe1c \u0111\u1ed1i t\u01b0\u1ee3ng l\xe0 'Static' trong Inspector.","\u0110\u1ea3m b\u1ea3o c\xe1c \u0111\u1ed1i t\u01b0\u1ee3ng chia s\u1ebb c\xf9ng m\u1ed9t Material v\xe0 Shader."],imageContext:"C\xe0i \u0111\u1eb7t 'Static' trong Inspector.",imageFile:"static-batching.png"},{name:"Texture Compression",category:"Memory Usage",description:"Gi\u1ea3m dung l\u01b0\u1ee3ng b\u1ed9 nh\u1edb Texture v\xe0 k\xedch th\u01b0\u1edbc file b\u1eb1ng c\xe1ch s\u1eed d\u1ee5ng c\xe1c thu\u1eadt to\xe1n n\xe9n nh\u01b0 ASTC.",impact:"Gi\u1ea3m s\u1eed d\u1ee5ng VRAM (b\u1ed9 nh\u1edb GPU), c\u1ea3i thi\u1ec7n th\u1eddi gian t\u1ea3i.",steps:["Set Texture Type l\xe0 'Default'.","Ch\u1ecdn Format n\xe9n (v\xed d\u1ee5: ASTC) trong Texture Importer."],imageContext:"Texture Import Settings",imageFile:"texture-settings.png"},{name:"GPU Instancing",category:"Draw Call Reduction",description:"Cho ph\xe9p GPU v\u1ebd nhi\u1ec1u b\u1ea3n sao (instances) c\u1ee7a c\xf9ng m\u1ed9t Mesh/Material trong m\u1ed9t Draw Call duy nh\u1ea5t.",impact:"Gi\u1ea3m \u0111\xe1ng k\u1ec3 Draw Calls khi v\u1ebd c\xe1c \u0111\u1ed1i t\u01b0\u1ee3ng gi\u1ed1ng nhau (c\xe2y c\u1ed1i, c\u1ecf, b\u1ee5i \u0111\xe1).",steps:["S\u1eed d\u1ee5ng Shader h\u1ed7 tr\u1ee3 Instancing.","\u0110\xe1nh d\u1ea5u \xf4 'Enable Instancing' tr\xean Material."],imageContext:"Instancing Material Settings",imageFile:"gpu-instancing.png"},{name:"Audio Compression",category:"Memory & Load Time",description:"S\u1eed d\u1ee5ng c\xe1c \u0111\u1ecbnh d\u1ea1ng n\xe9n ph\xf9 h\u1ee3p \u0111\u1ec3 gi\u1ea3m k\xedch th\u01b0\u1edbc b\u1ed9 nh\u1edb \xe2m thanh v\xe0 b\u0103ng th\xf4ng I/O. Compress 50% kh\xf4ng g\xe2y ra qu\xe1 nhi\u1ec1u s\u1ef1 kh\xe1c bi\u1ec7t v\u1ec1 \xe2m thanh \u1edf mobile",impact:"Gi\u1ea3m \u0111\xe1ng k\u1ec3 b\u1ed9 nh\u1edb RAM s\u1eed d\u1ee5ng cho \xe2m thanh v\xe0 t\u1ed1c \u0111\u1ed9 load scene.",steps:["Trong Audio Importer, ch\u1ecdn 'Compression Format' ph\xf9 h\u1ee3p.","Thi\u1ebft l\u1eadp 'Load Type' h\u1ee3p l\xfd."],imageContext:"Audio Import Settings Compression Format",imageFile:"audio-compression.png"},{name:"Profiler: CPU Analysis",category:"Analysis & Debugging",description:"Ph\xe2n t\xedch th\u1eddi gian CPU c\u1ee7a t\u1eebng h\xe0m (Scripts), Rendering, Physics \u0111\u1ec3 x\xe1c \u0111\u1ecbnh n\xfat c\u1ed5 chai ch\xednh \u0111ang chi\u1ebfm Frame Time.",impact:"Ph\xe1t hi\u1ec7n ch\xednh x\xe1c logic game ho\u1eb7c h\u1ec7 th\u1ed1ng n\xe0o \u0111ang l\xe0m ch\u1eadm game.",steps:["M\u1edf Profiler v\xe0 k\u1ebft n\u1ed1i v\u1edbi Development Build.","Theo d\xf5i bi\u1ec3u \u0111\u1ed3 CPU Usage v\xe0 ph\xe2n t\xedch c\xe2y ph\xe2n c\u1ea5p."],imageContext:"Unity Profiler CPU Usage Chart and Hierarchy",imageFile:"profiler-cpu.png"},{name:"Profiler: Memory Analysis",category:"Analysis & Debugging",description:"S\u1eed d\u1ee5ng Profiler \u0111\u1ec3 theo d\xf5i vi\u1ec7c s\u1eed d\u1ee5ng b\u1ed9 nh\u1edb (VRAM, RAM) c\u1ee7a Textures, Meshes v\xe0 c\xe1c \u0111\u1ed1i t\u01b0\u1ee3ng Game.",impact:"Gi\xfap t\u1ed1i \u01b0u h\xf3a VRAM/RAM, ng\u0103n ng\u1eeba crash do h\u1ebft b\u1ed9 nh\u1edb tr\xean thi\u1ebft b\u1ecb.",steps:["S\u1eed d\u1ee5ng ch\u1ee9c n\u0103ng 'Take Sample' ho\u1eb7c 'Take Snapshot' trong Memory Profiler.","Ph\xe2n t\xedch 'Used By Objects' v\xe0 'Assets'."],imageContext:"Unity Profiler Memory Snapshot and Texture breakdown",imageFile:"profiler-memory.png"},{name:"Mobile Shader Optimization",category:"Rendering/GPU",description:"\u01afu ti\xean s\u1eed d\u1ee5ng c\xe1c Shader t\u1ed1i gi\u1ea3n, kh\xf4ng ph\u1ee9c t\u1ea1p (v\xed d\u1ee5: Unlit, Diffuse, Mobile/VertexLit) thay v\xec c\xe1c Standard Shader n\u1eb7ng. \u0110i\u1ec1u n\xe0y gi\u1ea3m thi\u1ec3u t\xednh to\xe1n tr\xean GPU, \u0111\u1eb7c bi\u1ec7t quan tr\u1ecdng v\u1edbi chip di \u0111\u1ed9ng.",impact:"Gi\u1ea3m \u0111\xe1ng k\u1ec3 th\u1eddi gian Render Frame (SetPass Calls, Draw Calls), c\u1ea3i thi\u1ec7n FPS tr\xean c\xe1c thi\u1ebft b\u1ecb c\u1ea5p th\u1ea5p.",steps:["S\u1eed d\u1ee5ng Built-in Mobile Shaders ho\u1eb7c Shaders \u0111\u01b0\u1ee3c t\u1ed1i \u01b0u h\xf3a b\u1eb1ng Shader Graph (ch\u1ec9 b\u1eadt c\xe1c t\xednh n\u0103ng c\u1ea7n thi\u1ebft).","T\u1eaft c\xe1c t\xednh n\u0103ng kh\xf4ng c\u1ea7n thi\u1ebft nh\u01b0 Shadows, Realtime Reflections, Multi-pass rendering.","N\xean s\u1eed d\u1ee5ng c\xe1c Shaders ch\u1ec9 t\xednh to\xe1n trong Vertex (VertexLit) thay v\xec Pixel (Fragment) n\u1ebfu c\xf3 th\u1ec3."],imageFile:"mobile-shader.png",imageContext:"Bi\u1ec3u \u0111\u1ed3 so s\xe1nh chi ph\xed Shader (Overdraw & Complexity)."},{name:"TextMesh Pro (TMP) Usage",category:"UI/Batching",description:"TextMesh Pro (TMP) thay th\u1ebf cho UI Text truy\u1ec1n th\u1ed1ng v\xec TMP s\u1eed d\u1ee5ng k\u1ef9 thu\u1eadt Font Atlas v\xe0 Dynamic Batching hi\u1ec7u qu\u1ea3 h\u01a1n. \u0110i\u1ec1u n\xe0y gi\xfap gi\u1ea3m thi\u1ec3u Draw Calls cho c\xe1c ph\u1ea7n t\u1eed Text.",impact:"C\u1ea3i thi\u1ec7n t\u1ed1c \u0111\u1ed9 x\xe2y d\u1ef1ng UI (Canvas rebuild) v\xe0 gi\u1ea3m Draw Calls do Text.",steps:["Lu\xf4n s\u1eed d\u1ee5ng TextMesh Pro cho m\u1ecdi ph\u1ea7n t\u1eed Text trong game (thay v\xec Text legacy).","S\u1eed d\u1ee5ng chung m\u1ed9t Font Atlas gi\u1eefa c\xe1c TextMesh Pro components \u0111\u1ec3 t\u0103ng kh\u1ea3 n\u0103ng Batching.","Tr\xe1nh thay \u0111\u1ed5i m\xe0u s\u1eafc ho\u1eb7c k\xedch th\u01b0\u1edbc Text qu\xe1 th\u01b0\u1eddng xuy\xean n\u1ebfu kh\xf4ng c\u1ea7n thi\u1ebft, v\xec n\xf3 c\xf3 th\u1ec3 g\xe2y rebuild Canvas."],imageFile:"textmeshpro.png",imageContext:"So s\xe1nh hi\u1ec7u su\u1ea5t gi\u1eefa Text Mesh Pro v\xe0 Legacy Text."},{name:"Disable Raycast Target (UI)",category:"UI/Performance",description:"\u0110\u1ed1i v\u1edbi c\xe1c ph\u1ea7n t\u1eed UI ch\u1ec9 mang t\xednh trang tr\xed (decoration) ho\u1eb7c n\u1eb1m d\u01b0\u1edbi c\xe1c n\xfat b\u1ea5m kh\xe1c, vi\u1ec7c t\u1eaft 'Raycast Target' s\u1ebd ng\u0103n ch\xfang nh\u1eadn s\u1ef1 ki\u1ec7n Input. \u0110i\u1ec1u n\xe0y gi\xfap h\u1ec7 th\u1ed1ng Input c\u1ee7a Unity (Graphics Raycaster) l\xe0m vi\u1ec7c nhanh h\u01a1n.",impact:"Gi\u1ea3m \u0111\xe1ng k\u1ec3 chi ph\xed t\xednh to\xe1n Raycast tr\xean m\u1ed7i Frame, \u0111\u1eb7c bi\u1ec7t khi c\xf3 nhi\u1ec1u element trong Canvas.",steps:["Ch\u1ecdn ph\u1ea7n t\u1eed UI kh\xf4ng t\u01b0\u01a1ng t\xe1c (v\xed d\u1ee5: \u1ea3nh n\u1ec1n, icon, text t\u0129nh).","Trong Component 'Image' ho\u1eb7c 'Text', b\u1ecf ch\u1ecdn (Uncheck) t\xf9y ch\u1ecdn 'Raycast Target'.","Ch\u1ec9 b\u1eadt 'Raycast Target' cho c\xe1c n\xfat b\u1ea5m (Button), Toggle, Slider ho\u1eb7c c\xe1c element c\u1ea7n ph\u1ea3n h\u1ed3i Input."],imageFile:"disable-raycast.png",imageContext:"Giao di\u1ec7n Inspector khi t\u1eaft Raycast Target."},{name:"Multi-threaded Rendering (MTR)",category:"Rendering/CPU",description:"K\xedch ho\u1ea1t t\xednh n\u0103ng n\xe0y cho ph\xe9p Unity s\u1eed d\u1ee5ng nhi\u1ec1u lu\u1ed3ng CPU (Multi-threads) \u0111\u1ec3 chu\u1ea9n b\u1ecb v\xe0 g\u1eedi l\u1ec7nh v\u1ebd (Draw Calls) t\u1edbi GPU, thay v\xec ch\u1ec9 d\xf9ng Main Thread. \u0110i\u1ec1u n\xe0y \u0111\u1eb7c bi\u1ec7t quan tr\u1ecdng \u0111\u1ec3 tr\xe1nh t\xecnh tr\u1ea1ng 'CPU-bound'.",impact:"Gi\u1ea3m g\xe1nh n\u1eb7ng x\u1eed l\xfd Rendering tr\xean Main Thread, t\u0103ng t\u1ed1c \u0111\u1ed9 t\u1ed5ng th\u1ec3 c\u1ee7a Frame v\xe0 c\u1ea3i thi\u1ec7n FPS.",steps:["M\u1edf Player Settings (Edit -> Project Settings -> Player).","Trong ph\u1ea7n 'Other Settings', t\xecm v\xe0 b\u1eadt t\xf9y ch\u1ecdn 'Multithreaded Rendering'.","L\u01b0u \xfd: Ch\u1ec9 kh\u1ea3 d\u1ee5ng tr\xean c\xe1c n\u1ec1n t\u1ea3ng h\u1ed7 tr\u1ee3 (Mobile, PC) v\xe0 c\xf3 th\u1ec3 g\xe2y ra l\u1ed7i n\u1ebfu code kh\xf4ng 'thread-safe'."],imageFile:"multithread-rendering.png",imageContext:"Giao di\u1ec7n Player Settings khi b\u1eadt Multithreaded Rendering."},{name:"Lightmap Encoding (L\u01b0u tr\u1eef Lightmap)",category:"Memory/Rendering",description:"\u0110i\u1ec1u ch\u1ec9nh c\xe1ch c\xe1c Lightmap \u0111\u01b0\u1ee3c l\u01b0u tr\u1eef. Vi\u1ec7c s\u1eed d\u1ee5ng \u0111\u1ecbnh d\u1ea1ng n\xe9n (v\xed d\u1ee5: Low Quality/Compressed) thay v\xec \u0111\u1ecbnh d\u1ea1ng kh\xf4ng n\xe9n (High Quality/RGBM) gi\xfap gi\u1ea3m \u0111\xe1ng k\u1ec3 dung l\u01b0\u1ee3ng Lightmap trong b\u1ed9 nh\u1edb.",impact:"Gi\u1ea3m dung l\u01b0\u1ee3ng b\u1ed9 nh\u1edb VRAM v\xe0 dung l\u01b0\u1ee3ng file Build game, t\u0103ng t\u1ed1c \u0111\u1ed9 t\u1ea3i Scene.",steps:["M\u1edf Lighting Settings (Window -> Rendering -> Lighting).","Trong tab 'Baked Lightmaps', t\xecm ph\u1ea7n 'Lightmap Settings'.","Thay \u0111\u1ed5i 'Lightmap Encoding' t\u1eeb High Quality (RGBM) sang 'Low Quality' ho\u1eb7c 'Compressed' (Linear)."],imageFile:"lightmap-encoding.png",imageContext:"Giao di\u1ec7n Lighting Settings khi \u0111i\u1ec1u ch\u1ec9nh Lightmap Encoding."}],di=ua.section`
